import hashlib,json,pathlib,shutil
out=pathlib.Path('tests/release-evidence/20261011-pr182-exception-evidence')
cache=out/'matcher-proofs/__pycache__/historical_gate.cpython-312.pyc'
assert cache.is_file();cache.unlink();cache.parent.rmdir()
# The matcher probe imported the historical Python module; generated bytecode is not evidence payload.
shutil.copyfile(__file__,out/'executors/geometry-182-cause-clean-package.py')
(out/'packaging-note.json').write_text(json.dumps({'excluded_generated_file':'matcher-proofs/__pycache__/historical_gate.cpython-312.pyc',
    'reason':'Python import cache generated during the matcher probe; not a runtime receipt or source; ignored by Git',
    'runtime_raw_and_receipts_unchanged':True},indent=2)+'\n')
manifest=''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+p.relative_to(out).as_posix()+'\n'
                 for p in sorted(out.rglob('*')) if p.is_file() and p.name!='SHA256SUMS')
(out/'SHA256SUMS').write_text(manifest)
print(json.dumps({'payloads':len(manifest.splitlines()),'generated_bytecode_excluded':True}))
